#!/usr/bin/env node
// Keeps this connector in step with the AUniverse MCP server.
//
//   node scripts/sync.mjs                    regenerate every generated file from
//                                            connector.json and the catalogue snapshot
//   node scripts/sync.mjs --from <url|file>  first replace the snapshot with the server's
//                                            catalogue (GET /api/mcp/catalog), then regenerate
//   ... --from <url|file> --label "<text>"   say where the catalogue came from in the snapshot
//                                            (e.g. "AUniverse main @ a6013ac")
//   node scripts/sync.mjs --check            change nothing; exit 1 if any generated file is
//                                            stale (what CI runs)
//   node scripts/sync.mjs --check --from <url|file>
//                                            also exit 1 if the server's catalogue differs from
//                                            the snapshot, and say how
//   ... --accept-auth-change                 let --from take a catalogue whose server.auth or
//                                            server.transport changed (the client setups may need
//                                            rethinking first)
//   node scripts/sync.mjs --check --since <git ref>
//                                            compare the plugin with <ref> instead of the last
//                                            commit: exit 1 if it changed since then but
//                                            connector.json's version didn't go up (what CI runs)
//
// Node 20 or later, no dependencies. See MAINTAINING.md.

import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, realpathSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { claudeCode, codex } from './clients.mjs';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SNAPSHOT = 'catalog/auniverse-catalog.json';
const GENERATED_NOTE = 'Generated by scripts/sync.mjs from connector.json and catalog/auniverse-catalog.json. Do not edit by hand.';
// Directories that hold nothing but generated files.
const GENERATED_DIRS = ['.claude-plugin', 'plugins', 'templates'];
// Hand-written files: generated blocks are filled in, and the prose is checked for stale promises.
const HAND_WRITTEN = ['README.md', 'docs/claude-code.md', 'docs/codex.md', 'docs/troubleshooting.md', 'scripts/connect.sh'];
// connect.sh's token check calls this tool.
const CHECK_TOOL = 'auniverse_whoami';

// ---------- input ----------

function readText(path) {
  return readFileSync(join(ROOT, path), 'utf8');
}

function readJson(path) {
  const text = readText(path);
  try {
    return JSON.parse(text);
  } catch (error) {
    throw new Error(`${path}: ${error.message}`);
  }
}

function loadConnector() {
  const c = readJson('connector.json');
  const need = [
    'version', 'server.name', 'server.title', 'server.description', 'server.status', 'server.transport', 'server.url', 'server.site',
    'server.docs', 'server.catalog', 'server.token_page', 'auth.header', 'auth.scheme', 'auth.token_prefix',
    'auth.token_pattern', 'auth.env_var', 'plugin.marketplace', 'plugin.name', 'plugin.repo',
  ];
  for (const path of need) {
    const value = path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), c);
    if (typeof value !== 'string' || !value) throw new Error(`connector.json: ${path} must be a non-empty string`);
  }
  if (!/^[a-z][a-z0-9_-]*$/.test(c.server.name)) throw new Error('connector.json: server.name must be lower-case letters, digits, - or _');
  if (!/^[A-Z][A-Z0-9_]*$/.test(c.auth.env_var)) throw new Error('connector.json: auth.env_var must be an upper-case variable name');
  if (!/^\d+\.\d+\.\d+$/.test(c.version)) throw new Error('connector.json: version must look like 1.2.3');
  if (!['live', 'early-access'].includes(c.server.status)) throw new Error('connector.json: server.status must be "live" or "early-access"');
  if (c.server.status !== 'live' && (typeof c.server.status_note !== 'string' || !c.server.status_note)) {
    throw new Error('connector.json: server.status_note must say what to expect while the status is "early-access"');
  }
  return c;
}

async function fetchCatalog(source) {
  if (/^https?:\/\//.test(source)) {
    const response = await fetch(source, { headers: { accept: 'application/json' } });
    if (!response.ok) throw new Error(`GET ${source} answered ${response.status}`);
    return response.json();
  }
  return JSON.parse(readFileSync(source, 'utf8'));
}

// ---------- the catalogue snapshot ----------

const NAME = /^[A-Za-z0-9_.-]{1,128}$/;
const isObject = (value) => Boolean(value) && typeof value === 'object' && !Array.isArray(value);

function checkCatalogShape(catalog) {
  if (!isObject(catalog)) return ['not a JSON object'];
  const problems = [];
  if (!isObject(catalog.server)) problems.push('"server" is missing');
  else for (const f of ['name', 'version', 'transport', 'auth']) if (typeof catalog.server[f] !== 'string') problems.push(`server.${f} is missing`);
  for (const key of ['scopes', 'toolsets', 'tools', 'resources', 'prompts']) if (!Array.isArray(catalog[key])) problems.push(`"${key}" isn't a list`);
  if (problems.length) return problems;

  if (!catalog.tools.length) problems.push('it lists no tools');
  for (const tool of catalog.tools) {
    if (!isObject(tool) || typeof tool.name !== 'string' || !NAME.test(tool.name)) {
      problems.push(`a tool with a missing or unusual name (${JSON.stringify(isObject(tool) ? tool.name : tool)})`);
      continue;
    }
    if (typeof tool.title !== 'string' || typeof tool.description !== 'string') problems.push(`tool ${tool.name} has no title or description`);
    if (!isObject(tool.input_schema)) problems.push(`tool ${tool.name} has no input_schema`);
  }
  for (const s of catalog.scopes) if (!isObject(s) || typeof s.scope !== 'string' || !/^[A-Za-z0-9_.:-]+$/.test(s.scope)) problems.push('a scope with a missing or unusual name');
  for (const t of catalog.toolsets) if (!isObject(t) || typeof t.key !== 'string' || !NAME.test(t.key)) problems.push('a toolset with a missing or unusual key');
  for (const p of catalog.prompts) if (!isObject(p) || typeof p.name !== 'string' || !NAME.test(p.name)) problems.push('a prompt with a missing or unusual name');
  for (const r of catalog.resources) if (!isObject(r) || typeof r.uri !== 'string') problems.push('a resource without a URI');

  // The catalogue's text lands in Markdown, between the generated-block markers.
  const walk = (value, path) => {
    if (typeof value === 'string') {
      if (/<!--|-->|generated:/.test(value)) problems.push(`${path} contains "<!--", "-->" or "generated:"`);
    } else if (value && typeof value === 'object') {
      for (const [key, item] of Object.entries(value)) walk(item, `${path}.${key}`);
    }
  };
  walk(catalog, 'catalogue');
  return problems;
}

const originOf = (url) => {
  try {
    return new URL(url).origin;
  } catch {
    return null;
  }
};

function replaceEverywhere(value, pairs) {
  if (typeof value === 'string') {
    let out = value;
    for (const [from, to] of pairs) out = out.split(from).join(to);
    return out;
  }
  if (Array.isArray(value)) return value.map((v) => replaceEverywhere(v, pairs));
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, replaceEverywhere(v, pairs)]));
  }
  return value;
}

/**
 * The catalogue as any deployment serves it (local, staging, production), rewritten to the
 * production URLs so snapshots from different deployments compare equal. Whether the
 * connector is switched on is a deployment's state, not a server fact, so it is dropped.
 */
export function normaliseCatalog(raw, connector, source, label) {
  const problems = checkCatalogShape(raw);
  if (problems.length) throw new Error(`That isn't an AUniverse MCP catalogue: ${problems.join('; ')}`);
  const docs = String(raw.server.docs_url || '').replace(/\/+$/, '');
  const site = docs.endsWith('/developers/mcp') ? docs.slice(0, -'/developers/mcp'.length) : null;
  const pairs = [];
  if (raw.server.mcp_url) pairs.push([raw.server.mcp_url, connector.server.url]);
  if (docs) pairs.push([docs, connector.server.docs]);
  if (site) pairs.push([site, connector.server.site]);
  pairs.sort((a, b) => b[0].length - a[0].length);
  const { _snapshot, ...rest } = raw;
  const catalog = replaceEverywhere(rest, pairs);
  delete catalog.server.enabled;
  catalog.server.mcp_url = connector.server.url;

  // Anything still pointing at a deployment other than production would end up in the snapshot:
  // this computer, another host on the production site's domain, or wherever the catalogue came from.
  const production = new Set(
    [connector.server.url, connector.server.site, connector.server.docs, connector.server.catalog].map(originOf),
  );
  const siteHost = new URL(connector.server.site).hostname;
  const sources = new Set([raw.server.mcp_url, raw.server.docs_url, source].map((u) => u && originOf(u)).filter(Boolean));
  const foreign = (origin) => {
    if (production.has(origin)) return false;
    const host = new URL(origin).hostname;
    return sources.has(origin) || /^(localhost|127\.0\.0\.1|\[::1\])$/.test(host) || host === siteHost || host.endsWith(`.${siteHost}`);
  };
  const leftovers = [];
  const scan = (value, path) => {
    if (typeof value === 'string') {
      for (const [url] of value.matchAll(/https?:\/\/[^\s"'<>()\]]+/g)) {
        const origin = originOf(url);
        if (origin && foreign(origin)) leftovers.push(`${origin} (in ${path})`);
      }
    } else if (value && typeof value === 'object') {
      for (const [key, item] of Object.entries(value)) scan(item, `${path}.${key}`);
    }
  };
  scan(catalog, 'catalogue');
  if (leftovers.length) {
    const why = site
      ? 'Take the catalogue from a deployment whose URLs all follow its docs_url and mcp_url.'
      : "Its docs_url doesn't end in /developers/mcp, so the site's URL couldn't be worked out: take the catalogue from another deployment.";
    throw new Error(`After rewriting it to the production URLs, the catalogue still mentions ${[...new Set(leftovers)].join(', ')}. ${why}`);
  }

  const local = /^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])[:/]/.test(source);
  const from = label || (local ? 'a local development server' : /^https?:\/\//.test(source) ? source : 'a saved catalogue file');
  return { _snapshot: { synced_on: new Date().toISOString().slice(0, 10), from }, ...catalog };
}

/**
 * Only production's catalogue says whether the connector is switched on, and where. Compares that
 * with connector.json; empty when they agree or when the catalogue isn't production's.
 */
export function deploymentProblems(raw, connector, source) {
  if (!/^https?:\/\//.test(source) || originOf(source) !== originOf(connector.server.site)) return [];
  const problems = [];
  const enabled = raw.server.enabled === true;
  const live = connector.server.status === 'live';
  if (enabled && !live) {
    problems.push(`Production has the connector switched on, but connector.json's server.status is "${connector.server.status}": see "Going live" in MAINTAINING.md.`);
  }
  if (!enabled && live) {
    problems.push(`Production has the connector switched off, but connector.json's server.status is "live".`);
  }
  if (enabled && raw.server.mcp_url && raw.server.mcp_url !== connector.server.url) {
    problems.push(`Production serves the connector at ${raw.server.mcp_url}, but connector.json's server.url is ${connector.server.url}.`);
  }
  const docs = String(raw.server.docs_url || '').replace(/\/+$/, '');
  if (docs && docs !== connector.server.docs) {
    problems.push(`Production's docs are at ${docs}, but connector.json's server.docs is ${connector.server.docs}.`);
  }
  return problems;
}

function byKey(list, key) {
  return new Map((list || []).map((item) => [item[key], item]));
}

/** What changed between two snapshots, in words (empty when they match). */
export function describeChanges(before, after) {
  const lines = [];
  const fieldsChanged = (a, b, fields) => fields.filter((f) => JSON.stringify(a[f]) !== JSON.stringify(b[f]));

  const serverFields = ['name', 'version', 'mcp_url', 'docs_url', 'transport', 'auth', 'instructions'];
  for (const f of fieldsChanged(before.server, after.server, serverFields)) lines.push(`server.${f} changed`);

  const sections = [
    ['scope', 'scopes', 'scope', ['description', 'min_level']],
    ['toolset', 'toolsets', 'key', ['title', 'description', 'enabled', 'docs_url', 'tools']],
    ['tool', 'tools', 'name', ['title', 'description', 'toolset', 'action', 'required_scope', 'min_level', 'annotations', 'input_schema', 'output_schema']],
    ['resource', 'resources', 'uri', ['title', 'description', 'mime_type']],
    ['prompt', 'prompts', 'name', ['title', 'description']],
  ];
  // Whether a tool can change things matters for the hand-written promises (MAINTAINING.md).
  const marker = (label, old, now) => {
    if (label !== 'tool' || !writes(now)) return '';
    return !old ? ' (writes)' : writes(old) ? '' : ' (now writes)';
  };
  for (const [label, key, id, fields] of sections) {
    const a = byKey(before[key], id);
    const b = byKey(after[key], id);
    for (const [name, item] of b) if (!a.has(name)) lines.push(`new ${label}: ${name}${marker(label, null, item)}`);
    for (const name of a.keys()) if (!b.has(name)) lines.push(`${label} removed: ${name}`);
    for (const [name, item] of b) {
      if (!a.has(name)) continue;
      const changed = fieldsChanged(a.get(name), item, fields);
      if (changed.length) lines.push(`${label} ${name}: ${changed.join(', ')} changed${marker(label, a.get(name), item)}`);
    }
    // The generated docs follow the catalogue's order.
    const kept = (from, other) => [...from.keys()].filter((name) => other.has(name));
    if (JSON.stringify(kept(a, b)) !== JSON.stringify(kept(b, a))) lines.push(`${key} reordered`);
  }
  return lines;
}

/** A tool that isn't marked read-only may change things. */
export function writes(tool) {
  return !(tool.annotations && tool.annotations.readOnlyHint);
}

// ---------- rendering helpers ----------

const LEVEL_WORDS = {
  system: 'anyone with a token',
  limited: 'anyone with a token',
  user: 'all members',
  moderator: 'moderators (curators)',
  admin: 'admins',
  super_admin: 'super admins',
  owner: 'the owner',
};

function who(minLevel) {
  return LEVEL_WORDS[minLevel] || `level ${minLevel} and up`;
}

function cell(text) {
  return String(text ?? '').replace(/\s*\n\s*/g, ' ').replace(/\|/g, '\\|').trim();
}

function refName(ref) {
  return ref.split('/').pop();
}

function typeOf(schema, defs) {
  if (!schema || typeof schema !== 'object') return 'any';
  if (schema.$ref) {
    const def = defs[refName(schema.$ref)] || {};
    const keys = Object.keys(def.properties || {});
    return keys.length ? `{${keys.join(', ')}}` : refName(schema.$ref);
  }
  if (schema.anyOf) {
    const parts = schema.anyOf.filter((s) => s.type !== 'null').map((s) => typeOf(s, defs));
    return parts.join(' or ') || 'null';
  }
  if (schema.enum) return schema.enum.map((v) => JSON.stringify(v)).join(' | ');
  const limits = [];
  if (schema.type === 'string') {
    if (schema.format === 'date-time') return 'date-time';
    if (schema.maxLength != null) limits.push(`≤ ${schema.maxLength} chars`);
  }
  if (schema.type === 'integer' || schema.type === 'number') {
    if (schema.minimum != null && schema.maximum != null) limits.push(`${schema.minimum}–${schema.maximum}`);
    else if (schema.minimum != null) limits.push(`≥ ${schema.minimum}`);
    else if (schema.maximum != null) limits.push(`≤ ${schema.maximum}`);
  }
  if (schema.type === 'array') {
    const items = typeOf(schema.items || {}, defs);
    return `list of ${items}${schema.maxItems != null ? ` (at most ${schema.maxItems})` : ''}`;
  }
  return limits.length ? `${schema.type} (${limits.join(', ')})` : schema.type || 'any';
}

function argumentRows(inputSchema) {
  const defs = inputSchema.$defs || {};
  const required = new Set(inputSchema.required || []);
  return Object.entries(inputSchema.properties || {}).map(([name, schema]) => {
    const fallback = 'default' in schema && schema.default !== null ? `\`${JSON.stringify(schema.default)}\`` : '';
    const def = required.has(name) ? 'required' : fallback;
    let description = schema.description || '';
    // A field whose only description is on the referenced model (e.g. {board_id}).
    if (!description && schema.$ref) description = (defs[refName(schema.$ref)] || {}).description || '';
    return `| \`${name}\` | ${cell(typeOf(schema, defs))} | ${def} | ${cell(description)} |`;
  });
}

function hints(annotations = {}) {
  const words = [];
  words.push(annotations.readOnlyHint ? 'read-only' : annotations.destructiveHint ? 'writes (destructive)' : 'writes');
  if (annotations.idempotentHint) words.push('idempotent');
  if (annotations.openWorldHint) words.push('reaches outside AUniverse');
  return words.join(', ');
}

// ---------- generated files ----------

function toolsDoc(connector, catalog) {
  const out = [];
  out.push('# Tools, resources and prompts', '');
  out.push(`<!-- ${GENERATED_NOTE} -->`, '');
  out.push(
    `What the \`${catalog.server.name}\` server (version ${catalog.server.version}) offers, as of the snapshot taken on ${catalog._snapshot.synced_on}. ` +
      'Your assistant only sees what your account level allows, and every call acts as you: it never does more than you can on the website. ' +
      `The live list is always at [${connector.server.catalog}](${connector.server.catalog}), and the official guide at [${connector.server.docs}](${connector.server.docs}).`,
    '',
  );
  out.push('## Scopes', '', 'A token carries scopes. A scope only works while your account level allows it.', '');
  out.push('| Scope | What it allows | Who can have it |', '|---|---|---|');
  for (const s of catalog.scopes) out.push(`| \`${s.scope}\` | ${cell(s.description)} | ${cell(who(s.min_level))} |`);
  out.push('');

  for (const toolset of catalog.toolsets) {
    const tools = catalog.tools.filter((t) => t.toolset === toolset.key);
    out.push(`## ${toolset.title}`, '');
    out.push(`${toolset.description}${toolset.docs_url ? ` Official docs: [${toolset.docs_url}](${toolset.docs_url}).` : ''}`, '');
    if (!toolset.enabled) out.push('_Not switched on on the server yet._', '');
    for (const tool of tools) {
      out.push(`### \`${tool.name}\`: ${tool.title}`, '');
      out.push(tool.description.trim(), '');
      out.push(
        `- **Who:** ${who(tool.min_level)}${tool.required_scope ? `, with a token that has \`${tool.required_scope}\`` : ''}`,
        `- **Behaviour:** ${hints(tool.annotations)}`,
      );
      const rows = argumentRows(tool.input_schema);
      if (rows.length) {
        out.push('', '| Argument | Type | Default | Description |', '|---|---|---|---|', ...rows);
      } else {
        out.push('- **Arguments:** none');
      }
      out.push('');
    }
  }

  out.push('## Resources', '');
  if (catalog.resources.length) {
    out.push('| URI | Title | Format | What it is |', '|---|---|---|---|');
    for (const r of catalog.resources) out.push(`| \`${r.uri}\` | ${cell(r.title)} | ${cell(r.mime_type)} | ${cell(r.description)} |`);
  } else {
    out.push('None.');
  }
  out.push('', '## Prompts', '');
  if (catalog.prompts.length) {
    out.push('| Name | Title | What it does |', '|---|---|---|');
    for (const p of catalog.prompts) out.push(`| \`${p.name}\` | ${cell(p.title)} | ${cell(p.description)} |`);
  } else {
    out.push('None.');
  }
  out.push('', 'Resources and prompts are a convenience: everything also works with the tools alone.', '');
  return out.join('\n');
}

function toolsSummary(catalog) {
  const out = ['| Tool | What it does | Who |', '|---|---|---|'];
  for (const t of catalog.tools) out.push(`| \`${t.name}\` | ${cell(t.title)} | ${cell(who(t.min_level))} |`);
  return out.join('\n');
}

function statusNote(connector) {
  const { server } = connector;
  if (server.status === 'live') return `> **Status: live** at \`${server.url}\`.`;
  return `> **Status: early access.** ${server.status_note}`;
}

const shellQuote = (value) => `'${String(value).replace(/'/g, `'\\''`)}'`;

function shellConstants(connector) {
  const { server, auth, plugin } = connector;
  const values = {
    SERVER_NAME: server.name,
    DEFAULT_URL: server.url,
    DEFAULT_ENV_VAR: auth.env_var,
    AUTH_HEADER: auth.header,
    AUTH_SCHEME: auth.scheme,
    TOKEN_PREFIX: auth.token_prefix,
    TOKEN_PATTERN: auth.token_pattern,
    TOKEN_PAGE: server.token_page,
    STATUS_NOTE: server.status === 'live' ? '' : server.status_note,
    PLUGIN_REPO: plugin.repo,
    PLUGIN_MARKETPLACE: plugin.marketplace,
    PLUGIN_REF: `${plugin.name}@${plugin.marketplace}`,
  };
  return Object.entries(values).map(([k, v]) => `${k}=${shellQuote(v)}`).join('\n');
}

/** The token check for Windows without WSL, where connect.sh doesn't run. */
function checkPowershell(connector) {
  const { server, auth } = connector;
  const body = JSON.stringify({ jsonrpc: '2.0', id: 1, method: 'tools/call', params: { name: CHECK_TOOL, arguments: {} } });
  const headers = `@{ ${auth.header} = "${auth.scheme} $env:${auth.env_var}"; Accept = 'application/json, text/event-stream' }`;
  return ['```powershell', `(Invoke-RestMethod -Method Post ${server.url} -ContentType application/json -Headers ${headers} -Body '${body}').result.structuredContent`, '```'].join('\n');
}

// ---------- the generated set ----------

/** Every generated output: whole files, and marked blocks inside hand-written files. */
export function generate(connector, catalog, clients) {
  const files = new Map();
  const blocks = new Map(); // path -> Map(blockName -> content)
  const block = (path, name, content) => {
    if (!blocks.has(path)) blocks.set(path, new Map());
    blocks.get(path).set(name, content);
  };

  files.set('docs/tools.md', toolsDoc(connector, catalog));
  block('README.md', 'tools', toolsSummary(catalog));
  block('scripts/connect.sh', 'constants', shellConstants(connector));
  block('README.md', 'status', statusNote(connector));
  block('docs/troubleshooting.md', 'check-powershell', checkPowershell(connector));
  for (const client of clients) client(connector, catalog, { file: (p, c) => files.set(p, c), block });
  return { files, blocks };
}

const BLOCK_STYLES = {
  md: (name) => [`<!-- generated:${name} -->`, `<!-- /generated:${name} -->`],
  sh: (name) => [`# >>> generated:${name}`, `# <<< generated:${name}`],
};

function styleFor(path) {
  return path.endsWith('.sh') ? BLOCK_STYLES.sh : BLOCK_STYLES.md;
}

function fillBlocks(path, text, named) {
  let out = text;
  for (const [name, content] of named) {
    const [open, close] = styleFor(path)(name);
    const start = out.indexOf(open);
    const end = out.indexOf(close);
    if (start === -1 || end === -1 || end < start) throw new Error(`${path}: the generated:${name} markers are missing`);
    out = `${out.slice(0, start + open.length)}\n${content.replace(/\n+$/, '')}\n${out.slice(end)}`;
  }
  return out;
}

// ---------- checks beyond the generated text ----------

/** The hand-written part of a file: everything outside its generated blocks. */
function stripBlocks(path, text) {
  const pattern = path.endsWith('.sh')
    ? /# >>> generated:[^\n]*\n[\s\S]*?# <<< generated:[^\n]*/g
    : /<!-- generated:[^\n]*-->[\s\S]*?<!-- \/generated:[^\n]*-->/g;
  return text.replace(pattern, '');
}

/**
 * Promises in the hand-written prose that the catalogue or connector.json has made untrue. Each
 * entry names the files to edit; MAINTAINING.md has the details.
 */
export function staleProse(connector, catalog, texts) {
  const problems = [];
  const find = (pattern) => [...texts].filter(([path, text]) => pattern.test(stripBlocks(path, text))).map(([path]) => path);

  const writers = catalog.tools.filter(writes).map((t) => t.name);
  if (writers.length) {
    const files = find(/only reads/i);
    if (files.length) problems.push(`${writers.join(', ')} can change things, but ${files.join(', ')} still say every tool only reads.`);
  }
  if (connector.server.status === 'live') {
    const files = find(/before launch|in production yet|early access/i);
    if (files.length) problems.push(`The connector is live, but ${files.join(', ')} still talk about it before launch.`);
  }
  return problems;
}

/** Run git in the repository; null when git fails (no git, not a repository, unknown ref or path). */
function git(...args) {
  try {
    return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
  } catch {
    return null;
  }
}

// Files that operating systems and editors leave behind.
const JUNK = /(^|\/)(\.DS_Store|Thumbs\.db|desktop\.ini|\..*\.sw[a-p]|.*~)$/;

/** Files in the generated directories that the generator no longer writes. */
function strayFiles(files) {
  const listed = git('ls-files', '-z', '--cached', '--others', '--exclude-standard', '--', ...GENERATED_DIRS);
  let present;
  if (listed !== null) {
    present = listed.split('\0').filter((path) => path && !JUNK.test(path) && existsSync(join(ROOT, path)));
  } else {
    present = [];
    const walk = (dir) => {
      const full = join(ROOT, dir);
      if (!existsSync(full)) return;
      for (const entry of readdirSync(full, { withFileTypes: true })) {
        const path = `${dir}/${entry.name}`;
        if (entry.isDirectory()) walk(path);
        else if (!JUNK.test(path)) present.push(path);
      }
    };
    GENERATED_DIRS.forEach(walk);
  }
  return present.filter((path) => !files.has(path)).sort();
}

/** A commit git knows, or null. */
function commitOf(ref) {
  const sha = git('rev-parse', '--verify', '--quiet', `${ref}^{commit}`);
  return sha ? sha.trim() : null;
}

function gitShow(ref, path) {
  return git('show', `${ref}:./${path}`);
}

const versionParts = (version) => version.split('.').map(Number);

function isNewer(version, than) {
  const [a, b] = [versionParts(version), versionParts(than)];
  for (let i = 0; i < 3; i += 1) if (a[i] !== b[i]) return a[i] > b[i];
  return false;
}

/**
 * Claude Code only offers a plugin update when its version goes up. Compares the plugin about to be
 * written with commit `ref`; nothing to say when connector.json isn't in that commit.
 */
function versionProblems(ref, label, connector, files) {
  const base = gitShow(ref, 'connector.json');
  if (base === null) return [];
  let baseVersion;
  try {
    baseVersion = JSON.parse(base).version;
  } catch {
    return [];
  }
  if (typeof baseVersion !== 'string' || !/^\d+\.\d+\.\d+$/.test(baseVersion)) return [];
  const changed = [...files.keys()].filter((path) => path.startsWith('plugins/') && gitShow(ref, path) !== files.get(path));
  if (!changed.length || isNewer(connector.version, baseVersion)) return [];
  return [
    `The plugin changed since ${label} (${changed.join(', ')}), but connector.json's version is still ${connector.version}: ` +
      'raise it, or plugin users never get the change.',
  ];
}

// ---------- main ----------

async function main(argv) {
  const flags = ['--check', '--accept-auth-change'];
  const options = ['--from', '--label', '--since'];
  const valueOf = (flag) => {
    const i = argv.indexOf(flag);
    if (i === -1) return null;
    if (!argv[i + 1] || argv[i + 1].startsWith('--')) throw new Error(`${flag} needs a value`);
    return argv[i + 1];
  };
  const check = argv.includes('--check');
  const acceptAuthChange = argv.includes('--accept-auth-change');
  const source = valueOf('--from');
  const label = valueOf('--label');
  const since = valueOf('--since');
  if (label && !source) throw new Error('--label goes with --from');
  const values = new Set(options.map((f) => argv.indexOf(f) + 1).filter((i) => i > 0));
  const unknown = argv.filter((a, i) => !flags.includes(a) && !options.includes(a) && !values.has(i));
  if (unknown.length) throw new Error(`Unknown argument: ${unknown[0]}`);

  const connector = loadConnector();
  // --from replaces the snapshot, so one that won't parse (a merge conflict, say) is no obstacle.
  let snapshot = null;
  try {
    snapshot = readJson(SNAPSHOT);
  } catch (error) {
    if (!source) throw error;
    console.log(`${error.message}: replacing it.`);
  }
  if (since && !commitOf(since)) throw new Error(`--since: ${since} isn't a commit in this repository`);
  let newSnapshot = null;
  const stale = [];
  const needs = [];

  if (source) {
    const raw = await fetchCatalog(source);
    const live = normaliseCatalog(raw, connector, source, label);
    needs.push(...deploymentProblems(raw, connector, source));
    const changes = snapshot ? describeChanges(snapshot, live) : [`${SNAPSHOT} replaced`];
    if (changes.length) {
      console.log(`The server's catalogue differs from ${SNAPSHOT}:`);
      for (const line of changes) console.log(`  - ${line}`);
      if (check) {
        stale.push(SNAPSHOT);
        snapshot ??= live;
      } else {
        const authChanged = changes.some((line) => line === 'server.auth changed' || line === 'server.transport changed');
        if (authChanged && !acceptAuthChange) {
          throw new Error(
            "The server's auth or transport changed. The client setups (headers, tokens, the troubleshooting advice about sign-in) " +
              'may need rethinking before anything else: see MAINTAINING.md. Then run again with --accept-auth-change.',
          );
        }
        newSnapshot = live;
        snapshot = live;
      }
    } else {
      console.log(`The server's catalogue matches ${SNAPSHOT}.`);
    }
  }

  if (snapshot.server.name !== connector.server.name) {
    throw new Error(`The server is called "${snapshot.server.name}" but connector.json says "${connector.server.name}"`);
  }
  if (!String(snapshot.server.auth).includes(connector.auth.token_prefix)) {
    throw new Error(`The server's auth (${snapshot.server.auth}) no longer mentions ${connector.auth.token_prefix} tokens: check connector.json's auth`);
  }
  if (!String(snapshot.server.transport).startsWith('streamable-http')) {
    throw new Error(`The server's transport is now "${snapshot.server.transport}": check the client setups`);
  }
  if (!snapshot.tools.some((t) => t.name === CHECK_TOOL)) {
    throw new Error(`The server has no ${CHECK_TOOL} tool any more, and scripts/connect.sh's token check calls it: update check_token and summarise first`);
  }

  // Everything is generated in memory first, so a failure leaves the files as they were.
  const { files, blocks } = generate(connector, snapshot, [claudeCode, codex]);
  const pending = [];
  if (newSnapshot) pending.push([SNAPSHOT, `${JSON.stringify(newSnapshot, null, 2)}\n`, 'updated']);
  for (const [path, content] of files) {
    const full = join(ROOT, path);
    const current = existsSync(full) ? readFileSync(full, 'utf8') : null;
    if (current === content) continue;
    if (check) stale.push(path);
    else pending.push([path, content, 'wrote']);
  }
  const texts = new Map();
  for (const path of HAND_WRITTEN) texts.set(path, readText(path));
  for (const [path, named] of blocks) {
    const current = texts.get(path) ?? readText(path);
    const next = fillBlocks(path, current, named);
    texts.set(path, next);
    if (current === next) continue;
    if (check) stale.push(path);
    else pending.push([path, next, 'updated']);
  }
  const stray = strayFiles(files);
  if (stray.length) needs.push(`Not generated any more, so delete: ${stray.join(', ')}.`);
  needs.push(...staleProse(connector, snapshot, texts));
  // Against the last commit by default, so a change waiting to be committed is caught too.
  if (since) {
    const commit = commitOf(since);
    const label = commit.startsWith(since) ? commit.slice(0, 7) : `${since} (${commit.slice(0, 7)})`;
    needs.push(...versionProblems(since, label, connector, files));
  }
  else if (commitOf('HEAD')) needs.push(...versionProblems('HEAD', 'the last commit', connector, files));

  for (const [path, content, verb] of pending) {
    const full = join(ROOT, path);
    mkdirSync(dirname(full), { recursive: true });
    writeFileSync(full, content);
    console.log(`${verb} ${path}`);
  }
  if (newSnapshot) console.log('Review the changes above: some need hand edits too (MAINTAINING.md).');

  if (needs.length) {
    console.error('Needs a hand edit:');
    for (const line of needs) console.error(`  - ${line}`);
  }
  if (check && stale.length) {
    console.error(`Out of date: ${stale.join(', ')}. Run \`node scripts/sync.mjs${source ? ` --from ${source}` : ''}\` and commit the result.`);
  }
  if (needs.length || (check && stale.length)) process.exit(1);
  if (check) console.log('Everything generated is up to date.');
}

const invoked = (() => {
  try {
    return Boolean(process.argv[1]) && realpathSync(resolve(process.argv[1])) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
})();

if (invoked) {
  main(process.argv.slice(2)).catch((error) => {
    console.error(error.message);
    process.exit(2);
  });
}
